/**
 * @file
 * @brief Kernel initialization module
 *
 * This module contains routines that are used to initialize the kernel.
 */

#include <ctype.h>
#include <stdbool.h>
#include <string.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/printk.h>
#include <zephyr/debug/stack.h>
#include <zephyr/random/random.h>
#include <zephyr/linker/sections.h>
#include <zephyr/toolchain.h>
#include <zephyr/kernel_structs.h>
#include <zephyr/device.h>
#include <zephyr/init.h>
#include <zephyr/linker/linker-defs.h>
#include <zephyr/platform/hooks.h>
#include <ksched.h>
#include <kthread.h>
#include <ipi.h>
#include <zephyr/sys/dlist.h>
#include <kernel_internal.h>
#include <zephyr/drivers/entropy.h>
#include <zephyr/logging/log_ctrl.h>
#include <zephyr/tracing/tracing.h>
#include <zephyr/sys/barrier.h>
#include <zephyr/sys/libc-hooks.h>
#include <zephyr/pm/device_runtime.h>

#ifdef CONFIG_GCOV
#include <zephyr/debug/gcov.h>
#endif

/* the only struct z_kernel instance */
__pinned_bss
struct z_kernel _kernel;

__pinned_bss
atomic_t _cpus_active;

/* init/main and idle threads */
K_THREAD_PINNED_STACK_DEFINE(z_main_stack, CONFIG_MAIN_STACK_SIZE);
struct k_thread z_main_thread;

#ifdef CONFIG_MULTITHREADING
__pinned_bss
struct k_thread z_idle_threads[CONFIG_MP_MAX_NUM_CPUS];

static K_KERNEL_PINNED_STACK_ARRAY_DEFINE(z_idle_stacks,
					  CONFIG_MP_MAX_NUM_CPUS,
					  CONFIG_IDLE_STACK_SIZE);
#endif /* CONFIG_MULTITHREADING */

extern const struct init_entry __init_start[];
extern const struct init_entry __init_EARLY_start[];
extern const struct init_entry __init_PRE_KERNEL_1_start[];
extern const struct init_entry __init_PRE_KERNEL_2_start[];
extern const struct init_entry __init_POST_KERNEL_start[];
extern const struct init_entry __init_APPLICATION_start[];
extern const struct init_entry __init_end[];

enum init_level {
	INIT_LEVEL_EARLY = 0,
	INIT_LEVEL_PRE_KERNEL_1,
	INIT_LEVEL_PRE_KERNEL_2,
	INIT_LEVEL_POST_KERNEL,
	INIT_LEVEL_APPLICATION,
#ifdef CONFIG_SMP
	INIT_LEVEL_SMP,
#endif /* CONFIG_SMP */
};

#ifdef CONFIG_SMP
extern const struct init_entry __init_SMP_start[];
#endif /* CONFIG_SMP */

/*
 * storage space for the interrupt stack
 *
 * Note: This area is used as the system stack during kernel initialization,
 * since the kernel hasn't yet set up its own stack areas. The dual purposing
 * of this area is safe since interrupts are disabled until the kernel context
 * switches to the first thread.
 */
K_KERNEL_PINNED_STACK_ARRAY_DEFINE(z_interrupt_stacks,
				   CONFIG_MP_MAX_NUM_CPUS,
				   CONFIG_ISR_STACK_SIZE);

extern void idle(void *unused1, void *unused2, void *unused3);

/* LCOV_EXCL_START */
FUNC_NORETURN __weak void __stack_chk_fail(void)
{
	printk("* STACK CHK FAIL! *\n");
	k_panic();
	CODE_UNREACHABLE;
}
/* LCOV_EXCL_STOP */

#ifdef CONFIG_STACK_CANARIES
#ifdef CONFIG_STACK_CANARIES_TLS
extern __thread volatile uintptr_t __stack_chk_guard;
#else
extern volatile uintptr_t __stack_chk_guard;
#endif /* CONFIG_STACK_CANARIES_TLS */
#endif /* CONFIG_STACK_CANARIES */

#if defined(CONFIG_DEMAND_PAGING) && !defined(CONFIG_LINKER_GENERIC_SECTIONS_PRESENT_AT_BOOT)
extern void z_paging_init_from_boot(void);
#endif

/**
 * @brief Perform any architecture-specific initialization
 *
 * This routine performs any architecture-specific initialization that is
 * needed before the kernel is ready to run.
 */
__weak void arch_kernel_init(void)
{
}

/**
 * @brief Clear BSS
 *
 * This routine clears the BSS region, so all bytes are 0.
 */
__boot_func
void z_bss_zero(void)
{
	if (IS_ENABLED(CONFIG_SKIP_BSS_CLEAR)) {
		return;
	}

	(void)memset(__bss_start, 0, __bss_end - __bss_start);
#if DT_NODE_HAS_STATUS_OKAY(DT_CHOSEN(zephyr_ccm))
	(void)memset(&__ccm_bss_start, 0,
		     (uintptr_t) &__ccm_bss_end - (uintptr_t) &__ccm_bss_start);
#endif
#if DT_NODE_HAS_STATUS_OKAY(DT_CHOSEN(zephyr_dtcm))
	(void)memset(&__dtcm_bss_start, 0,
		     (uintptr_t) &__dtcm_bss_end - (uintptr_t) &__dtcm_bss_start);
#endif
#if DT_NODE_HAS_STATUS_OKAY(DT_CHOSEN(zephyr_ocm))
	(void)memset(&__ocm_bss_start, 0,
		     (uintptr_t) &__ocm_bss_end - (uintptr_t) &__ocm_bss_start);
#endif
#ifdef CONFIG_CODE_DATA_RELOCATION
	extern void bss_zeroing_relocation(void);

	bss_zeroing_relocation();
#endif	/* CONFIG_CODE_DATA_RELOCATION */
#ifdef CONFIG_COVERAGE_GCOV
	(void)memset(&__gcov_bss_start, 0,
		     ((uintptr_t) &__gcov_bss_end - (uintptr_t) &__gcov_bss_start));
#endif /* CONFIG_COVERAGE_GCOV */
#ifdef CONFIG_NOCACHE_MEMORY
	if (IS_ENABLED(CONFIG_NOCACHE_MEMORY)) {
		(void)memset(&__nocache_bss_start, 0,
			     (uintptr_t)&__nocache_bss_end - (uintptr_t)&__nocache_bss_start);
	}
#endif
}

#ifdef CONFIG_LINKER_USE_BOOT_SECTION
/**
 * @brief Clear BSS within the bot region
 *
 * This routine clears the BSS within the boot region.
 * This is separate from z_bss_zero() as boot region may
 * contain symbols required for the boot process before
 * paging is initialized.
 */
__boot_func
void z_boot_bss_zero(void)
{
	(void)memset(&lnkr_boot_bss_start, 0,
		     (uintptr_t)&lnkr_boot_bss_end
		     - (uintptr_t)&lnkr_boot_bss_start);
}
#endif /* CONFIG_LINKER_USE_BOOT_SECTION */

#ifdef CONFIG_LINKER_USE_PINNED_SECTION
/**
 * @brief Clear BSS within the pinned region
 *
 * This routine clears the BSS within the pinned region.
 * This is separate from z_bss_zero() as pinned region may
 * contain symbols required for the boot process before
 * paging is initialized.
 */
__boot_func
void z_pinned_bss_zero(void)
{
	(void)memset(&lnkr_pinned_bss_start, 0,
		     (uintptr_t)&lnkr_pinned_bss_end
		     - (uintptr_t)&lnkr_pinned_bss_start);
}
#endif /* CONFIG_LINKER_USE_PINNED_SECTION */

#ifdef CONFIG_STACK_CANARIES
#ifdef CONFIG_ENTROPY_HAS_DRIVER
static void z_stack_canary_init(void)
{
	uintptr_t stack_guard;
	const struct device *const entropy = DEVICE_DT_GET_OR_NULL(DT_CHOSEN(zephyr_entropy));

	if ((entropy != NULL) && device_is_ready(entropy) &&
	    (entropy_get_entropy(entropy, (void *)&stack_guard, sizeof(stack_guard)) == 0)) {
		__stack_chk_guard = stack_guard;
	} else {
		sys_rand_get((void *)&stack_guard, sizeof(stack_guard));
		__stack_chk_guard = stack_guard;
	}
	__stack_chk_guard <<= 8;
}
#else
static void z_stack_canary_init(void)
{
	uintptr_t stack_guard;

	sys_rand_get((void *)&stack_guard, sizeof(stack_guard));
	__stack_chk_guard = stack_guard;
	__stack_chk_guard <<= 8;
}
#endif /* CONFIG_ENTROPY_HAS_DRIVER */
#endif /* CONFIG_STACK_CANARIES */

__pinned_func
int z_device_init(const struct device *dev)
{
	int rc = 0;

	if (dev->ops.init != NULL) {
		rc = dev->ops.init(dev);
		/* If initialization failed, record in dev->state->init_res
		 * the POSITIVE value of the errno. Note that this value will
		 * be truncated if it exceeds UINT8_MAX.
		 */
		if (rc < 0) {
			rc = -rc;
		}
		if (rc > UINT8_MAX) {
			rc = UINT8_MAX;
		}
		dev->state->init_res = rc;
	}

	dev->state->initialized = true;

	if (rc == 0) {
		/* Run automatic device runtime enablement */
		(void)pm_device_runtime_auto_enable(dev);
	}

	return -rc;
}

/**
 * @brief Execute all the init entry initialization functions at a given level
 *
 * @details Invokes the initialization routine for each init entry object
 * created by the INIT_ENTRY_DEFINE() macro using the specified level.
 * The linker script places the init entry objects in memory in the order
 * they need to be invoked, with symbols indicating where one level leaves
 * off and the next one begins.
 *
 * @param level init level to run.
 */
__pinned_func
static void z_sys_init_run_level(enum init_level level)
{
	static const struct init_entry *levels[] = {
		__init_EARLY_start,
		__init_PRE_KERNEL_1_start,
		__init_PRE_KERNEL_2_start,
		__init_POST_KERNEL_start,
		__init_APPLICATION_start,
#ifdef CONFIG_SMP
		__init_SMP_start,
#endif /* CONFIG_SMP */
		/* End marker */
		__init_end,
	};
	const struct init_entry *entry;

	for (entry = levels[level]; entry < levels[level+1]; entry++) {
		const struct device *dev = entry->dev;

		if (dev != NULL) {
			if ((dev->flags & DEVICE_FLAG_INIT_DEFERRED) == 0U) {
				(void)z_device_init(dev);
			}
		} else {
			(void)entry->init_fn();
		}
	}
}

/**
 * @brief Mainline for kernel's background thread
 *
 * This routine initializes the kernel mechanisms and executes the application's
 * main() function.
 */
__boot_func
static void bg_thread_main(void *unused1, void *unused2, void *unused3)
{
	ARG_UNUSED(unused1);
	ARG_UNUSED(unused2);
	ARG_UNUSED(unused3);

#ifdef CONFIG_MMU
	/* Invoked here such that backing store or eviction algorithms may
	 * initialize kernel objects, and that all POST_KERNEL and later tasks
	 * may perform memory management tasks (except for z_phys_map() which
	 * is allowed at any time)
	 */
	z_mem_manage_init();
#endif /* CONFIG_MMU */
	z_sys_post_kernel = true;

#if CONFIG_STACK_POINTER_RANDOM
	z_stack_adjust_initialized = 1;
#endif /* CONFIG_STACK_POINTER_RANDOM */
	soc_per_core_init_hook();

	z_sys_init_run_level(INIT_LEVEL_POST_KERNEL);

	soc_late_init_hook();

	board_late_init_hook();

	if (IS_ENABLED(CONFIG_CPP)) {
		z_cpp_init_static();
	}

	/* Final init level before app starts */
	z_sys_init_run_level(INIT_LEVEL_APPLICATION);

#ifdef CONFIG_STACK_SENTINEL
	/* Note that the main thread's stack is used during kernel init
	 * and may have had a lot of stack usage before this point.
	 */
	z_stack_sentinel_init();
#endif /* CONFIG_STACK_SENTINEL */

#ifdef CONFIG_BOOT_BANNER
	if (IS_ENABLED(CONFIG_BOOT_DELAY) && (CONFIG_BOOT_DELAY > 0)) {
		static const unsigned int boot_delay = CONFIG_BOOT_DELAY;

		printk("***** delaying boot " STRINGIFY(CONFIG_BOOT_DELAY)
		       "ms (per build configuration) *****\n");
		k_busy_wait(CONFIG_BOOT_DELAY * USEC_PER_MSEC);
		ARG_UNUSED(boot_delay);
	}
	BOOT_BANNER_PRINTK("*** Booting " CONFIG_BOOT_BANNER_STRING " ***\n");
#ifdef CONFIG_NCS_BOOT_BANNER
	BOOT_BANNER_PRINTK("*** Using nRF Connect SDK " NCS_COMMIT_STRING " ***\n");
#endif /* CONFIG_NCS_BOOT_BANNER */
#ifdef CONFIG_ZEPHYR_BOOT_BANNER
	BOOT_BANNER_PRINTK("*** Using Zephyr OS " ZEPHYR_COMMIT_STRING " ***\n");
#endif /* CONFIG_ZEPHYR_BOOT_BANNER */
#endif /* CONFIG_BOOT_BANNER */

#ifdef CONFIG_SMP
	if (!IS_ENABLED(CONFIG_SMP_BOOT_DELAY)) {
		z_smp_init();
	}
	z_sys_init_run_level(INIT_LEVEL_SMP);
#endif /* CONFIG_SMP */

#ifdef CONFIG_GCOV
	gcov_static_init();
#endif /* CONFIG_GCOV */

	extern int main(void);

	(void)main();

	/* Mark nonessential since main() has no more work to do */
	z_main_thread.base.user_options &= ~K_ESSENTIAL;

#ifdef CONFIG_COVERAGE_DUMP
	/* Dump coverage data once the main() has exited. */
	gcov_coverage_dump();
#endif /* CONFIG_COVERAGE_DUMP */
} /* LCOV_EXCL_LINE ... because we just dumped final coverage data */

#if defined(CONFIG_MULTITHREADING)
__boot_func
static void init_idle_thread(int i)
{
	struct k_thread *thread = &z_idle_threads[i];
	k_thread_stack_t *stack = z_idle_stacks[i];
	size_t stack_size = K_KERNEL_STACK_SIZEOF(z_idle_stacks[i]);

#ifdef CONFIG_THREAD_NAME
	char tname[8];

	if (CONFIG_MP_MAX_NUM_CPUS > 1) {
		snprintk(tname, sizeof(tname), "idle %02d", i);
	} else {
		snprintk(tname, sizeof(tname), "idle");
	}
#else
	char *tname = NULL;
#endif /* CONFIG_THREAD_NAME */

	z_setup_new_thread(thread, stack,
			   stack_size, idle, &_kernel.cpus[i],
			   NULL, NULL, K_LOWEST_THREAD_PRIO, K_ESSENTIAL,
			   tname);
	z_mark_thread_as_started(thread);

#ifdef CONFIG_SMP
	thread->base.is_idle = 1U;
#endif /* CONFIG_SMP */
}

void z_init_cpu(int id)
{
	init_idle_thread(id);
	_kernel.cpus[id].idle_thread = &z_idle_threads[id];
	_kernel.cpus[id].id = id;
	_kernel.cpus[id].irq_stack =
		(K_KERNEL_STACK_BUFFER(z_interrupt_stacks[id]) +
		 K_KERNEL_STACK_SIZEOF(z_interrupt_stacks[id]));
#ifdef CONFIG_SCHED_CPU_MASK_PIN_ONLY
	_kernel.cpus[id].idle_thread->base.cpu_mask = 1 << id;
#endif /* CONFIG_SCHED_CPU_MASK_PIN_ONLY */
}

/**
 * @brief Initialize kernel
 *
 * This routine is invoked when the system is ready to run C code. The
 * processor must be running in 32-bit mode, and the BSS must have been
 * cleared/zeroed.
 *
 * @return Does not return
 */
__boot_func
FUNC_NORETURN void z_cstart(void)
{
	/* gcov hook needed to get the coverage report.*/
	gcov_static_init();

	/* initialize early init calls */
	z_sys_init_run_level(INIT_LEVEL_EARLY);

	/* perform any architecture-specific initialization */
	arch_kernel_init();

	/* initialize log_core before any log message islogged */
	LOG_CORE_INIT();

#if defined(CONFIG_MULTITHREADING)
	/* Note: The z_ready_thread() call in prepare_multithreading() requires
	 * a dummy thread even if CONFIG_ARCH_HAS_CUSTOM_SWAP_TO_MAIN=y
	 */
	struct k_thread dummy_thread;

	z_dummy_thread_init(&dummy_thread);
#endif /* CONFIG_MULTITHREADING */

	/* perform basic hardware initialization */
	z_device_state_init();

	soc_early_init_hook();

	board_early_init_hook();

	z_sys_init_run_level(INIT_LEVEL_PRE_KERNEL_1);
	z_sys_init_run_level(INIT_LEVEL_PRE_KERNEL_2);

#ifdef CONFIG_CALL_TIMING_FUNCTIONS_AT_BOOT
	timing_init();
	timing_start();
#endif /* CONFIG_CALL_TIMING_FUNCTIONS_AT_BOOT */

#ifdef CONFIG_STACK_CANARIES
	z_stack_canary_init();
#endif /* CONFIG_STACK_CANARIES */

#ifdef CONFIG_MMU
	z_mem_manage_boot_finish();
#endif /* CONFIG_MMU */

#ifdef CONFIG_DEMAND_PAGING
#ifndef CONFIG_LINKER_GENERIC_SECTIONS_PRESENT_AT_BOOT
	/* Page in the non-pinned sections if they are not present in
	 * memory at boot.
	 */
	z_paging_init_from_boot();
#endif /* !CONFIG_LINKER_GENERIC_SECTIONS_PRESENT_AT_BOOT */
#endif /* CONFIG_DEMAND_PAGING */

	/* display boot banner */

#ifdef CONFIG_MULTITHREADING
	/* initialize kernel data structures */
	prepare_multithreading();

	/* invoke the background thread */
	z_switch_to_main_thread();
#else
#ifdef ARCH_SWITCH_TO_MAIN_NO_MULTITHREADING
	/* Custom ARCH-specific routine to switch to main()
	 * in the case of no multi-threading.
	 */
	ARCH_SWITCH_TO_MAIN_NO_MULTITHREADING(bg_thread_main,
		K_THREAD_STACK_BUFFER(z_main_stack),
		K_THREAD_STACK_SIZEOF(z_main_stack));
#else
	bg_thread_main(NULL, NULL, NULL);

	/* LCOV_EXCL_START
	 * We've already dumped coverage data at this point.
	 */
	irq_lock();
	while (true) {
	}
	/* LCOV_EXCL_STOP */
#endif /* ARCH_SWITCH_TO_MAIN_NO_MULTITHREADING */
#endif /* CONFIG_MULTITHREADING */

	/*
	 * Compiler can't tell that the above routines won't return and issues
	 * a warning unless we explicitly tell it that control never gets this
	 * far.
	 */

	CODE_UNREACHABLE; /* LCOV_EXCL_LINE */
}
#else /* CONFIG_MULTITHREADING */
#error "Single-threaded execution is not supported in this configuration"
#endif /* CONFIG_MULTITHREADING */
